public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (resultMap == null || target == null) {
        throw new IllegalArgumentException("The resultMap and the target graph cannot be null");
    }

    // Add all vertices to the target graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        target.addVertex(entry.getValue());
    }

    // Add all edges to the target graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String[] edges = entry.getValue().getEdges();
        if (edges != null) {
            for (String edge : edges) {
                if (resultMap.containsKey(edge)) {
                    target.addEdge(entry.getValue(), resultMap.get(edge));
                }
            }
        }
    }
}

