/**
* Returns a prime number which is &gt;= desiredCapacity and very close to desiredCapacity (within 11% if desiredCapacity &gt;= 1000).
* @param desiredCapacity the capacity desired by the user.
* @return the capacity which should be used for a hashtable.
*/
public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 3) {
        return 3;
    }
    // Check if the number is already prime
    for (int i = 2; i <= Math.sqrt(desiredCapacity); i++) {
        if (desiredCapacity % i == 0) {
            return desiredCapacity;
        }
    }
    // Find the next prime number
    int prime = 2;
    while (prime < desiredCapacity) {
        prime += 2;
    }
    return prime;
}

