/**
* Returns an edge connecting previously returned node with node, which will be returned next. If either of the mentioned nodes is virtual, the edge will be incident to its real counterpart.
*
* @return an edge from the current node to the next node
*/
Edge edgeToNext() {
    // Check if either of the nodes is virtual
    if (currentNode.isVirtual()) {
        Edge edge = new Edge(currentNode.getRealNode(), nextNode);
        // Compute the weight of the edge based on the distance between the real nodes
        edge.setWeight(computeWeight(currentNode.getRealNode(), nextNode));
        return edge;
    } else {
        // If both nodes are real, return an edge between them directly
        return new Edge(currentNode, nextNode);
    }
}

// Compute the weight of the edge based on the distance between the two nodes
private double computeWeight(Node realNode1, Node realNode2) {
    // Compute the distance between the two nodes using the manhattan distance metric
    double distance = Math.abs(realNode1.getX() - realNode2.getX()) + Math.abs(realNode1.getY() - realNode2.getY());
    // Convert the distance to a weight between 0 and 1
    return distance / (graph.getMaxX() + graph.getMaxY());
}

