/**
 * Converts the specified character to a String that contains the one character.
 *
 * For ASCII 7 bit characters, this uses a cache that will return the same String object each time.
 *
 * @param ch the character to convert
 * @return a String containing the one specified character
 */
public static String toString(final char ch) {
    // Check the cache for the existing String instance
    final Stringstr = cachedToString(ch);
    if (str != null) {
        return str;
    }

    // If no cached instance exists, create a new one
    str = new String(new char[] { ch });

    // Cache the new instance for future use
    cacheToString(ch, str);

    return str;
}

private static String cachedToString(final char ch) {
    // Check if the cache contains the requested character
    final String str = cache.get(ch);
    if (str != null) {
        return str;
    }

    return null;
}

private static void cacheToString(final char ch, final String str) {
    // Cache the new instance for future use
    cache.put(ch, str);
}

