public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();

    // Open the file for reading
    BufferedReader reader = new BufferedReader(new FileReader(file));

    // Skip the header
    String line = reader.readLine();
    if (line.startsWith("# Snapshot time")) {
        line = reader.readLine();
    }

    // Read each snapshot in the file
    while ((line = reader.readLine()) != null) {
        // Skip empty lines
        if (line.trim().isEmpty()) {
            continue;
        }

        // Split the line into parts
        String[] parts = line.split(":");
        if (parts.length > 7) {
            // Get the snapshot properties
            int id = Integer.parseInt(parts[0]);
            long timestamp = Long.parseLong(parts[1]);
            String snapshotName = parts[2];
            String md5sum = parts[3];
            String buildType = parts[4];
            String os = parts[5];
            String cpu = parts[6];

            // Check if the snapshot is within the time range
            TimeInterval timeInterval = TimeInterval.create(timestamp, snapshotName);
            if (timeRanges.stream().anyMatch(timeRange -> timeRange.isIncluded(timeInterval))) {
                // Add the snapshot to the list
                snapshots.add(new ThreadSnapshot(id, timestamp, snapshotName, md5sum, buildType, os, cpu));
            }
        }
    }

    // Close the file
    reader.close();

    return snapshots;
}
